# 酸碱 pH 标尺探索台
ph = 7   # 溶液的 pH 值

hide()
# 彩虹色标尺（15 段实心块）
i = 0
while i < 15:
    px = -196 + i * 27
    col = "#dc2626"
    if i == 1:
        col = "#ef4444"
    if i == 2:
        col = "#f87171"
    if i == 3:
        col = "#fb923c"
    if i == 4:
        col = "#fbbf24"
    if i == 5:
        col = "#facc15"
    if i == 6:
        col = "#a3e635"
    if i == 7:
        col = "#22c55e"
    if i == 8:
        col = "#2dd4bf"
    if i == 9:
        col = "#38bdf8"
    if i == 10:
        col = "#60a5fa"
    if i == 11:
        col = "#3b82f6"
    if i == 12:
        col = "#4f46e5"
    if i == 13:
        col = "#7c3aed"
    if i == 14:
        col = "#9333ea"
    fill_rect(px + 13, 40, 26, 40, col)
    write(i, px + 13, 72, "#475569", 9)
    i = i + 1
# 指示三角 + 试管
px2 = -196 + ph * 27
fill_rect(px2, -4, 10, 14, "#f97316")
fill_rect(px2, 52, 10, 20, "#f97316")
fill_rect(-40, -110, 24, 90, "#e2e8f0")
mycol = "#22c55e"
if ph < 6.8:
    mycol = "#dc2626"
if ph > 7.2:
    mycol = "#4f46e5"
fill_rect(-40, -105, 18, 55, mycol)
write("pH = " + ph, 90, -80, mycol, 20)
if ph < 6.8:
    write("酸性：数值越小越酸", 30, -40, "#dc2626", 13)
if ph > 7.2:
    write("碱性：数值越大越碱", 30, -40, "#4f46e5", 13)
if ph >= 6.8:
    if ph <= 7.2:
        write("中性（纯水）", 30, -40, "#16a34a", 13)
